                                      "[:bar] :percent ", double total = 100) {
  const char *format = formatSEXP[0];
  RProgress::RProgress pb(format, total);

  pb.tick(0);
  for (int i = 0; i < 100; i++) {
    usleep( (useconds_t) (2.0 / 100 * 1000000));
    pb.tick();
  }

  Rcpp::CharacterVector result(1);
  result[0] = "DONE";
  return result;
}
```

